		private static void stPolishAlarm_ToByteBase(ref byte[] dst, Array src, int len = 1, int wordOffset = 0) {
			int[] indices = NewIndices(src);
			int offset = wordOffset;
			for (int i = 0; i < len; i++) {
				NextIndices(src, indices);
				stPolishAlarm_ToByte(ref dst, (stPolishAlarm)src.GetValue(indices), len, wordOffset);
				wordOffset += stPolishAlarm_WSIZE;
			}
		}
